import json,calendar
from pathlib import Path
R=[]
def add(date,code,year,title,summary,url,source,evidence,ref):
 R.append(dict(date=date,code=code,year=year,title=title,summary=summary,url=url,source_title=source,evidence=evidence,confidence='date et rattachement vérifiés',research_ref=ref))
add('07-01','CAN',1867,'Naissance de la Confédération canadienne','L’Acte de l’Amérique du Nord britannique entre en vigueur. Les provinces initiales sont réunies au sein du Dominion du Canada, étape fondatrice de la fédération actuelle.','https://www.canada.ca/en/canadian-heritage/campaigns/canada-day/about.html','Patrimoine canadien','Date d’entrée en vigueur explicitement donnée : 1 juillet 1867.','turn167search5')
add('07-02','USA',1776,'Le vote américain pour l’indépendance','Le Congrès continental adopte la résolution d’indépendance. Le texte de la Déclaration sera adopté deux jours plus tard : vote politique et déclaration publiée sont deux moments distincts.','https://www.archives.gov/founding-docs/timeline','National Archives','La chronologie donne July 2, 1776 : Lee Resolution Adopted.','turn167search3')
add('07-03','DZA',1962,'Reconnaissance de l’indépendance algérienne','La France reconnaît officiellement l’indépendance algérienne après le référendum. La célébration nationale algérienne est fixée au 5 juillet : il ne faut pas confondre ces deux dates.','https://www.musee-armee.fr/ExpositionAlgerie/independent-algeria-1962.html','Musée de l’Armée','Reconnaissance française le 3 juillet, célébration algérienne le 5 juillet.','turn167search30')
add('07-04','USA',1776,'Adoption de la Déclaration d’indépendance','Le Congrès continental adopte le texte proclamant la séparation des treize colonies de la couronne britannique. Cette adoption est le repère commémoré par la fête nationale américaine.','https://www.archives.gov/historical-docs/declaration','National Archives','Adoption le 4 juillet 1776 ; copie signée distincte du 2 août.','turn167search4')
add('07-05','VEN',1811,'La déclaration d’indépendance du Venezuela','Les représentants de sept provinces approuvent la rupture avec la couronne espagnole. La déclaration constitue un acte fondateur, mais la guerre pour rendre cette indépendance effective se poursuit.','https://www.mincultura.gob.ve/wp-content/uploads/2022/07/Acta-de-la-Independencia-del-5-de-julio-de-1811.pdf','Ministère vénézuélien de la Culture','Acte d’indépendance daté du 5 juillet 1811.','turn171search7')
add('07-06','MWI',1964,'L’indépendance du Malawi','Le Nyassaland, auparavant sous souveraineté britannique, accède à l’indépendance sous le nom de Malawi. Cette date ouvre une nouvelle étape politique pour ce pays d’Afrique australe.','https://history.state.gov//countries/malawi','Office of the Historian','Indépendance explicitement datée July 6, 1964.','turn171search3')
add('07-07','SLB',1978,'L’indépendance des Îles Salomon','Les Îles Salomon deviennent un État indépendant, après la période de souveraineté britannique. L’archipel entre alors dans une nouvelle phase de ses relations internationales.','https://2009-2017.state.gov/documents/organization/38522.pdf','Département d’État américain — traités','La notice indique le 7 juillet 1978 comme date de l’indépendance.','turn171search8')
add('07-08','PRT',1497,'Vasco de Gama quitte Lisbonne','La flotte commandée par Vasco de Gama quitte Lisbonne pour son voyage vers l’Inde par le cap de Bonne-Espérance. Cette expédition est un jalon majeur de l’expansion maritime portugaise.','https://antt.dglab.gov.pt/wp-content/uploads/sites/17/2025/02/vasco-da-gama-viagem.pdf','Archives nationales Torre do Tombo','Départ de Lisbonne : 8 de Julho de 1497.','turn171search9')
add('07-09','ARG',1816,'L’indépendance proclamée à Tucumán','Le Congrès de Tucumán proclame la rupture des Provinces-Unies du Río de la Plata avec la monarchie espagnole. Cette déclaration est au cœur de la fête nationale argentine du 9 juillet.','https://www.argentina.gob.ar/noticias/9-de-julio-de-1816-declaracion-de-la-independencia-de-la-argentina','Gouvernement argentin','Déclaration explicitement datée mardi 9 juillet 1816.','turn174search1')
add('07-10','BHS',1973,'Les Bahamas deviennent indépendantes','L’indépendance des Bahamas prend effet. Le pays choisit de rester membre du Commonwealth, tout en devenant un État souverain.','https://www.bahamashclondon.net/default/political/','Haut-commissariat des Bahamas à Londres','État souverain indépendant le 10 July 1973 et maintien au Commonwealth.','turn174search24')
add('07-11','MNG',1921,'Un nouveau gouvernement en Mongolie','Le gouvernement populaire mongol est proclamé dans le cadre d’une monarchie aux pouvoirs limités. Le 11 juillet devient un repère de la révolution de 1921 ; ce n’est pas la date de proclamation de la république de 1924.','https://tile.loc.gov/storage-services/public/gdcmassbookdig/mongoliacountrys00word_0/mongoliacountrys00word_0.pdf','Library of Congress — Mongolia: a country study','Chronologie : July 11, 1921, People’s Government, limited monarchy, proclaimed.','turn176search8')
add('07-12','STP',1975,'L’indépendance de São Tomé-et-Príncipe','São Tomé-et-Príncipe accède à l’indépendance après la domination portugaise. La date constitue un repère central de l’histoire politique de cet archipel du golfe de Guinée.','https://turismo.gov.st/en/pourquoi-sao-tome-et-principe/culture-et-patrimoine/journey-through-ages','Office du tourisme de São Tomé-et-Príncipe','Indépendance explicitement donnée au 12 juillet 1975.','turn174search30')
add('07-13','MNE',1878,'Reconnaissance internationale du Monténégro','Le congrès de Berlin reconnaît le Monténégro comme État indépendant. Le pays commémore aussi le 13 juillet le soulèvement de 1941 : la fête associe deux épisodes historiques distincts.','https://www.gov.me/en/digital-museum/13-july-symbol-of-montenegrin-statehood','Gouvernement du Monténégro — musée numérique','Reconnaissance le 13 juillet 1878, également soulèvement du 13 juillet 1941.','turn176search2')
add('07-14','FRA',1789,'Le 14 juillet et la Révolution française','La prise de la Bastille, le 14 juillet 1789, devient un symbole de la Révolution. La fête nationale adoptée en 1880 renvoie également à la fête de la Fédération du 14 juillet 1790.','https://www.elysee.fr/la-presidence/la-fete-nationale-du-14-juillet','Présidence de la République française','Source vérifiée par le parent : Bastille1789, Fédération1790, fête nationale1880.','parent-verified')
add('07-15','POL',1410,'La bataille de Grunwald','Les forces du royaume de Pologne et du grand-duché de Lituanie affrontent l’ordre Teutonique à Grunwald. Leur victoire demeure un épisode majeur de l’histoire médiévale de la région.','https://zpe.gov.pl/a/the-great-war-with-the-teutonic-knights/DdvwgoZZJ','Plateforme éducative du gouvernement polonais','Bataille explicitement datée du 15 juillet 1410.','turn182search24')
add('07-16','USA',1969,'Le départ d’Apollo 11','Apollo 11 décolle de Floride avec Neil Armstrong, Buzz Aldrin et Michael Collins. La mission doit réaliser un alunissage habité puis ramener l’équipage sur Terre.','https://www.nasa.gov/mission/apollo-11/','NASA','Launch July 16, 1969 ; objectif alunissage habité et retour.','turn176search7')
add('07-17','ITA',1998,'Le Statut de Rome est adopté','Une conférence diplomatique réunie en Italie adopte le Statut de Rome, traité fondateur de la Cour pénale internationale. La Cour ne naît juridiquement qu’à son entrée en vigueur en 2002.','https://www.icc-cpi.int/publications/core-legal-texts/rome-statute-international-criminal-court','Cour pénale internationale','Adoption17 juillet1998 ; entrée en vigueur1 juillet2002.','turn179search1')
add('07-18','ESP',1936,'Le soulèvement militaire gagne l’Espagne','Le soulèvement commencé le 17 juillet au Maroc espagnol s’étend à la péninsule le 18. Son échec à renverser immédiatement le gouvernement ouvre la guerre civile espagnole : il ne s’agit pas d’un commencement uniforme en un seul jour.','https://www.rtve.es/noticias/20260718/guerra-civil-franquismo-90-aniversario-18-de-julio-historia/17149968.shtml','RTVE — service public espagnol','Chronologie explicite17/18 juillet ; recoupée PARES ministèreCulture.','turn182search23')
add('07-19','NIC',1979,'La victoire de la révolution sandiniste','Une coalition dominée par les sandinistes prend le pouvoir après la fin du régime Somoza. Le 19 juillet devient le repère commémoratif de cette révolution nicaraguayenne.','https://media.defense.gov/2024/Oct/02/2003557339/-1/-1/0/20241001_NICARAGUA%20%28CONTRAS%29_1978-90.PDF','US Army War College — étude historique','Prise de pouvoir explicitement datée19 juillet1979.','turn179search26')
add('07-20','COL',1810,'Une junte de gouvernement à Santafé','Les événements de Santafé conduisent à la formation d’une junte. Le 20 juillet symbolise aujourd’hui l’indépendance colombienne, mais celle-ci résulte d’un processus prolongé et n’est pas entièrement acquise ce jour-là.','https://www.archivogeneral.gov.co/dia-de-la-independencia-20-de-julio-de-1810','Archives générales de la Nation colombienne','20 juillet1810 ; junte à Santafé, commencement du processus.','turn182search2')
add('07-21','BEL',1831,'Le serment du premier roi des Belges','Léopold Ier prête le serment constitutionnel et devient le premier roi des Belges. La fête nationale commémore ce serment, et non la proclamation de l’indépendance de1830.','https://www.monarchie.be/en/royal-family/history','Monarchie belge','Serment constitutionnel le21 juillet1831 ; indépendance1830.','turn182search7')
add('07-22','POL',1942,'Les déportations du ghetto de Varsovie','Dans la Pologne occupée, les autorités nazies commencent les déportations massives du ghetto de Varsovie vers le centre de mise à mort de Treblinka. Cette date rappelle la persécution et l’assassinat des Juifs de Varsovie.','https://encyclopedia.ushmm.org/content/en/article/the-holocaust-and-world-war-ii-key-dates','United States Holocaust Memorial Museum','Déportations commencées le22 juillet1942.','turn193search9')
add('07-23','EGY',1952,'Le mouvement des Officiers libres','Les Officiers libres prennent le contrôle de points stratégiques du Caire. Ce mouvement militaire entraîne la chute de la monarchie égyptienne ; la proclamation de la République intervient l’année suivante.','https://sis.gov.eg/en/egypt/society/days-and-occasions/the-july-23rd-revolution/','Service officiel égyptien de l’information','Opération datée du23 juillet1952.','turn193search0')
add('07-24','TUR',1923,'La signature du traité de Lausanne','Le traité de Lausanne règle la paix entre la Turquie et plusieurs puissances après les conflits de la fin de l’Empire ottoman. Il précède la proclamation de la République turque, en octobre1923.','https://www.mfa.gov.tr/data/Kutuphane/Yayinlar/bern.pdf','Ministère turc des Affaires étrangères','Signature24 juillet1923.','turn193search53')
add('07-25','TUN',1957,'La Tunisie devient une république','L’Assemblée constituante abolit la monarchie et proclame la République tunisienne. Cette transformation institutionnelle intervient après l’indépendance obtenue en1956 : les deux événements ne doivent pas être confondus.','https://www.justice.gov.tn/index.php?L=3&id=437','Ministère tunisien de la Justice','Proclamation25 juillet1957.','turn193search2')
add('07-26','LBR',1847,'La proclamation de la République du Liberia','Le Liberia se déclare république indépendante. Le territoire avait été colonisé sous l’impulsion de l’American Colonization Society, une organisation américaine ; il ne s’agissait pas d’une colonie administrée officiellement par le gouvernement des États-Unis.','https://www.loc.gov/item/today-in-history/july-26','Bibliothèque du Congrès','Proclamation26 juillet1847.','turn195search7')
add('07-27','KOR',1953,'L’armistice de la guerre de Corée','Un armistice met fin aux principaux combats de la guerre de Corée. Il est signé par les commandements des Nations unies, nord-coréen et des volontaires chinois. La Corée du Sud ne le signe pas ; ce n’est pas un traité de paix.','https://www.unc.mil/History/1951-1953-Armistice-Negotiations/','United Nations Command','Signature27 juillet1953 ; parties signataires précisées.','turn195search11')
add('07-28','PER',1821,'L’indépendance proclamée à Lima','José de San Martín proclame publiquement l’indépendance du Pérou à Lima. L’acte avait été signé plus tôt en juillet ; les combats pour consolider cette indépendance se poursuivent après la proclamation.','https://comunicaciones.congreso.gob.pe/noticias/peru-celebra-195-anos-de-independencia/','Congrès de la République du Pérou','Proclamation28 juillet1821 ; acte15 juillet.','turn195search30')
add('07-29','USA',1958,'La loi créant la NASA','Le président Dwight Eisenhower signe la loi qui crée la NASA. L’agence spatiale civile américaine commence effectivement ses activités le1er octobre suivant, dans le contexte de la compétition spatiale.','https://www.nasa.gov/history/president-eisenhower-signs-nasa-into-existence/','NASA','Loi signée29 juillet1958, activité1 octobre.','turn195search4')
add('07-30','VUT',1980,'La naissance du Vanuatu indépendant','L’ancien condominium franco-britannique des Nouvelles-Hébrides devient la République de Vanuatu. L’indépendance met fin à une administration coloniale partagée entre la France et le Royaume-Uni.','https://www.gov.vu/index.php/about/about-vanuatu','Gouvernement du Vanuatu','Pleine souveraineté30 juillet1980.','turn196search21')
add('07-31','MYS',1960,'La fin officielle de l’état d’urgence en Malaisie','Le gouvernement de la Fédération de Malaya déclare officiellement terminé l’état d’urgence commencé en1948. Cette date marque la fin administrative de cette phase du conflit, sans signifier la disparition immédiate de toute violence.','https://www.awm.gov.au/collection/CN18','Australian War Memorial','État d’urgence déclaré terminé31 juillet1960.','turn210search3')
add('08-01','BEN',1960,'Le Dahomey accède à l’indépendance','Le territoire devient indépendant sous le nom de République du Dahomey. Il porte aujourd’hui le nom de Bénin : rappeler l’ancien nom permet de replacer cette étape de la décolonisation dans son contexte.','https://www.gouv.bj/pages/histoire/','Gouvernement du Bénin','Souveraineté1 août1960 sous le nom Dahomey.','turn196search4')
add('08-02','KWT',1990,'L’invasion du Koweït','Les forces irakiennes envahissent le Koweït. Le Conseil de sécurité des Nations unies condamne l’invasion le jour même et exige le retrait des forces irakiennes. L’événement déclenche une crise internationale majeure.','https://www.un.org/Depts/oip/background/chron.html','Nations unies','Invasion2 août1990 et résolution660.','turn196search5')
add('08-03','NER',1960,'L’indépendance du Niger','Le Niger accède à l’indépendance après la période coloniale française. Sa demande d’admission aux Nations unies mentionne explicitement cette date comme celle de son accession à la pleine souveraineté.','https://treaties.un.org/doc/source/docs/niger.pdf','Nations unies — demande d’admission du Niger','Pleine indépendance3 août1960.','turn210search36')
add('08-05','BFA',1960,'L’indépendance de la Haute-Volta','La Haute-Volta devient indépendante après la domination coloniale française. Le pays adoptera plus tard le nom de Burkina Faso : cette date concerne l’indépendance, et non le changement de nom.','https://1997-2001.state.gov/background_notes/burkina_0398_bgn.html','Département d’État américain — notice historique','Indépendance5 août1960.','turn210search4')
add('08-04','BEL',1914,'L’invasion de la Belgique','L’armée allemande envahit la Belgique neutre pour avancer vers la France. L’invasion entraîne l’entrée en guerre du Royaume-Uni et place le territoire belge au cœur de la Première Guerre mondiale.','https://www.iwm.org.uk/sites/default/files/press-release/4_August_1914_Factsheet.pdf','Imperial War Museums','Chronologie de l’invasion du4 août1914.','turn222search7')
add('08-06','BOL',1825,'La Bolivie proclame son indépendance','La Bolivie déclare son indépendance de l’Espagne. Cette naissance politique intervient dans le contexte des guerres d’indépendance sud-américaines ; sa reconnaissance diplomatique par d’autres États suit des calendriers différents.','https://history.state.gov/countries/bolivia','Office of the Historian américain','Déclaration6 août1825.','turn222search0')
add('08-07','CIV',1960,'L’indépendance de la Côte d’Ivoire','La Côte d’Ivoire devient indépendante. Cette étape de la décolonisation met fin à la souveraineté française sur le territoire ; Félix Houphouët-Boigny dirige alors le gouvernement ivoirien.','https://history.state.gov/historicaldocuments/frus1958-60v14/d67','Office of the Historian — archives diplomatiques','Indépendance7 août1960.','turn222search1')
add('08-08','THA',1967,'À Bangkok, la naissance de l’ASEAN','La Thaïlande accueille la signature de la déclaration fondatrice de l’ASEAN. L’Indonésie, la Malaisie, les Philippines, Singapour et la Thaïlande créent ensemble cette organisation de coopération régionale.','https://asean.org/the-founding-of-asean/','ASEAN','Signature à Bangkok8 août1967.','turn222search4')
add('08-09','SGP',1965,'Singapour devient indépendante','La proclamation d’indépendance de Singapour est diffusée à la radio. La cité-État quitte la Fédération de Malaisie moins de deux ans après l’avoir rejointe et commence une nouvelle étape de son histoire politique.','https://www.nlb.gov.sg/main/article-detail?cmsuuid=139cd6b7-7672-4163-9640-db47447e9399','Bibliothèque nationale de Singapour','Proclamation radiodiffusée9 août1965.','turn224search5')
add('08-10','ECU',1809,'Quito forme une junte de gouvernement','À Quito, un mouvement renverse les autorités locales et constitue une junte. Cette journée est un jalon du processus d’émancipation ; elle ne correspond pas à l’indépendance définitivement acquise de l’Équateur.','https://www.presidencia.gob.ec/wp-content/uploads/downloads/2013/01/2008-08-10-DiezAgosto-199-aniversario.pdf','Présidence de l’Équateur','Constitution de la junte10 août1809.','turn224search8')
add('08-11','TCD',1960,'L’indépendance du Tchad','L’indépendance du Tchad est proclamée après la période de l’Afrique-Équatoriale française. La date marque son accession à la souveraineté, dans une année de décolonisation particulièrement importante pour le continent africain.','https://history.state.gov/countries/chad','Office of the Historian américain','Indépendance proclamée11 août1960.','turn224search3')
add('08-12','CHE',1949,'Les quatre Conventions de Genève','La conférence diplomatique convoquée par la Suisse adopte quatre conventions protégeant les victimes de guerre. Elles concernent notamment les blessés, les naufragés, les prisonniers et les civils. Genève devient ainsi un repère majeur du droit humanitaire.','https://ihl-databases.icrc.org/en/ihl-treaties/geneva-finact-1949/final-act','Comité international de la Croix-Rouge — acte final','Acte final12 août1949, conférence convoquée par Conseil fédéral.','turn224search4')
add('08-13','DEU',1961,'Berlin commence à être coupée par le mur','Les autorités est-allemandes ferment la frontière autour de Berlin-Ouest, d’abord avec des barbelés. Les murs et obstacles se renforcent ensuite. Cette séparation devient un symbole de la guerre froide et bouleverse la vie des habitants.','https://www.stiftung-berliner-mauer.de/de/themen/die-berliner-mauer','Fondation du Mur de Berlin','Fermeture commencée13 août1961.','turn225search0')
add('08-14','PAK',1947,'Le transfert de pouvoir au Pakistan','Lord Mountbatten s’adresse à l’Assemblée constituante du Pakistan lors du transfert de pouvoir. Le14 août devient la fête de l’indépendance pakistanaise ; Muhammad Ali Jinnah prête son serment de gouverneur général le lendemain.','https://www.na.gov.pk/en/content.php?id=75','Assemblée nationale du Pakistan','Transfert14 août1947 ; serment15 août.','turn225search5')
add('08-15','IND',1947,'L’indépendance de l’Inde','L’Inde devient indépendante du pouvoir colonial britannique. Cette émancipation s’accompagne de la partition du sous-continent. La date permet de découvrir une histoire qui associe lutte politique, naissance de nouveaux États et déplacements de populations.','https://www.india.gov.in/explore-india/facts-of-india/independence-day','Portail national de l’Inde','Indépendance15 août1947.','turn225search3')
add('08-16','CYP',1960,'La République de Chypre devient indépendante','La République de Chypre est proclamée État indépendant, sur la base des accords de Zurich et de Londres. Sa Constitution entre en vigueur à cette même date, après la période d’administration britannique.','https://www.gov.cy/cm/en/council-of-ministers/background/','Gouvernement de Chypre','État indépendant proclamé16 août1960.','turn225search4')
add('08-17','IDN',1945,'L’indépendance indonésienne est proclamée','À Jakarta, Sukarno et Mohammad Hatta proclament l’indépendance de l’Indonésie. La proclamation n’achève pas immédiatement la lutte : la souveraineté du nouvel État reste disputée durant les années suivantes.','https://kemlu.go.id/files/repositori/74504/Business%20Guide%20Indonesia-EN.pdf','Ministère indonésien des Affaires étrangères','Proclamation17 août1945.','turn226search5')
add('08-18','AUS',1966,'La bataille de Long Tan','Des soldats australiens, appuyés notamment par des artilleurs néo-zélandais, combattent à Long Tan au Vietnam. La date est devenue en Australie un jour de commémoration des anciens combattants de la guerre du Vietnam.','https://www.awm.gov.au/commemoration/long-tan','Australian War Memorial','Bataille18 août1966 ; commémoration annuelle.','turn226search0')
add('08-19','AFG',1919,'Le jour de l’indépendance afghane','Le19 août est la date retenue pour commémorer l’indépendance de l’Afghanistan en1919. Cette suggestion présente un anniversaire national : elle ne prétend pas que tous les actes diplomatiques liés à cette indépendance ont été signés ce même jour.','https://mfa.gov.af/en/page/26289','Ministère afghan des Affaires étrangères — calendrier commémoratif','19 août1919 indiqué comme Independence Day ; formulation volontairement commémorative.','turn226search1')
add('08-20','SEN',1960,'Le Sénégal quitte la Fédération du Mali','Le Sénégal se retire de la Fédération du Mali et proclame son indépendance comme État distinct. Il faut distinguer cette rupture politique de l’indépendance obtenue par la Fédération quelques semaines auparavant.','https://history.state.gov//countries/senegal','Office of the Historian américain','Retrait et déclaration20 août1960.','turn226search2')
add('08-21','USA',1959,'Hawaï devient le cinquantième État','Le président Eisenhower proclame l’admission d’Hawaï comme cinquantième État américain. Cette date concerne son statut dans l’Union ; elle ne doit pas masquer l’histoire antérieure du royaume hawaïen, de son renversement et de l’annexion.','https://www.archives.gov/legislative/features/hawaii','Archives nationales américaines','Admission21 août1959.','turn237search0')
add('08-22','HTI',1791,'La nuit du soulèvement de Saint-Domingue','Dans la nuit du22 au23 août, une insurrection d’esclaves commence à Saint-Domingue, dans l’actuelle Haïti. Ce soulèvement ouvre une phase décisive de la révolution haïtienne. L’anniversaire international est commémoré le23.','https://www.unesco.org/en/days/slave-trade-remembrance?hub=66748','UNESCO','Nuit du22 au23 août1791 explicitement indiquée.','turn237search2')
add('08-23','EST',1989,'La Voie balte relie trois peuples','Une chaîne humaine relie l’Estonie, la Lettonie et la Lituanie pour réclamer la liberté. Cette manifestation pacifique se déroule cinquante ans après le pacte germano-soviétique et participe aux mouvements de restauration de leurs indépendances.','https://www.unesco.org/en/memory-world/baltic-way-human-chain-linking-three-states-their-drive-freedom','UNESCO — Mémoire du monde','Chaîne humaine23 août1989.','turn237search3')
add('08-24','UKR',1991,'L’Ukraine déclare son indépendance','Le Parlement ukrainien adopte l’acte d’indépendance de l’Ukraine. Le texte prend effet immédiatement et prévoit un référendum de confirmation, organisé en décembre. Cette déclaration constitue un jalon de la dissolution de l’Union soviétique.','https://zakon.rada.gov.ua/rada/show/1427-12?lang=en','Verkhovna Rada — acte original','Acte adopté24 août1991.','turn237search4')
add('08-25','URY',1825,'La déclaration de la Province orientale','À Florida, les représentants de la Province orientale déclarent sa séparation du Brésil et votent son union aux Provinces-Unies du Río de la Plata. Cette étape ne doit pas être confondue avec la reconnaissance ultérieure de l’Uruguay comme État indépendant.','https://www.gub.uy/ministerio-educacion-cultura/comunicacion/noticias/25-agosto-1825-declaratoria-independencia-0','Ministère uruguayen de l’Éducation — Archives nationales','Lois d’indépendance et d’union votées25 août1825.','turn241search0')
add('08-26','FRA',1789,'La Déclaration des droits de l’homme et du citoyen','L’Assemblée nationale adopte la Déclaration des droits de l’homme et du citoyen. Le texte affirme notamment la liberté, l’égalité en droits et la souveraineté nationale, tout en ouvrant une histoire longue et conflictuelle de leur mise en œuvre.','https://www.legifrance.gouv.fr/Droit-francais/Constitution/Declaration-des-Droits-de-l-Homme-et-du-Citoyen-de-1789','Légifrance — texte original','Déclaration datée26 août1789.','turn241search3')
add('08-27','MDA',1991,'La Moldavie proclame son indépendance','Le Parlement réuni à Chișinău adopte la déclaration d’indépendance de la République de Moldavie. Le document affirme sa souveraineté dans le contexte de la désagrégation de l’Union soviétique.','https://presedinte.md/app/webroot/Constitutia_RM/Constitutia_RM_EN.pdf','Présidence moldave — déclaration originale','Adoptée27 août1991.','turn241search7')
add('08-28','USA',1963,'La marche sur Washington','Une grande manifestation pour l’emploi et la liberté rassemble des participants à Washington. Elle devient un moment majeur du mouvement américain pour les droits civiques et de la lutte contre les discriminations raciales.','https://www.archives.gov/legislative/features/march-on-washington','Archives nationales américaines','Marche28 août1963.','turn241search5')
add('08-29','SVK',1944,'Le soulèvement national slovaque','Une insurrection commence contre l’occupation allemande et le régime slovaque allié aux nazis. Organisé notamment autour de Banská Bystrica, ce soulèvement constitue un épisode majeur de la résistance en Slovaquie.','https://www.nationalww2museum.org/war/articles/slovak-national-uprising-1944','National WWII Museum','Ordre de soulèvement29 août1944.','turn245search3')
add('08-30','TLS',1999,'Le vote qui ouvre la voie à l’indépendance','Lors d’une consultation organisée par les Nations unies, les électeurs du Timor oriental rejettent l’autonomie proposée au sein de l’Indonésie. Le résultat ouvre une transition vers l’indépendance, malgré les violences qui suivent.','https://peacekeeping.un.org/sites/default/files/past/unmiset/background.html','Nations unies — maintien de la paix','Consultation30 août1999 ; résultats et transition.','turn245search4')
add('08-31','MYS',1957,'L’indépendance de la Fédération de Malaya','L’indépendance est proclamée au stade Merdeka de Kuala Lumpur. Il s’agit de la Fédération de Malaya ; la fédération élargie appelée Malaysia se formera en1963. Les deux dates correspondent à des étapes différentes.','https://www.parlimen.gov.my/maklumat-umum.html?Jul=&lang=en&uweb=dr','Parlement de Malaisie','Déclaration31 août1957.','turn245search7')
add('09-01','POL',1939,'L’invasion de la Pologne','L’Allemagne nazie envahit la Pologne. Cette attaque ouvre la Seconde Guerre mondiale en Europe et entraîne les déclarations de guerre britannique et française deux jours plus tard. La population polonaise subit ensuite une occupation dévastatrice.','https://encyclopedia.ushmm.org/content/en/timeline-event/holocaust/1939-1941/german-invasion-of-poland','United States Holocaust Memorial Museum','Invasion1 septembre1939.','turn245search9')
add('09-02','VNM',1945,'La déclaration d’indépendance du Vietnam','À Hanoï, Hô Chi Minh lit la déclaration d’indépendance de la République démocratique du Vietnam. Cette proclamation intervient à la fin de la Seconde Guerre mondiale ; elle ne met pas fin aux conflits sur la souveraineté du territoire.','https://vietnam.gov.vn/default.aspx?catname=national-flag-emblem-anthem-declaration-of-independence-68960','Portail gouvernemental vietnamien — déclaration','Lecture2 septembre1945 à Ba Đình.','turn249search0')
add('09-03','QAT',1971,'L’indépendance du Qatar','Le Qatar déclare son indépendance et met fin au traité qui organisait sa relation de protection avec le Royaume-Uni. Cette date de souveraineté est distincte de la fête nationale qatarienne célébrée en décembre.','https://www.diwan.gov.qa/ar-QA/About-Qatar/History-of-Qatar?sc_lang=en','Diwan de l’émir du Qatar','Déclaration3 septembre1971.','turn249search5')
add('09-04','FRA',1870,'La République est proclamée','Après la défaite du Second Empire à Sedan, la République est proclamée à Paris. Ce changement ouvre la Troisième République, dont les institutions seront progressivement stabilisées au cours des années suivantes.','https://www2.assemblee-nationale.fr/decouvrir-l-assemblee/juniors/histoire/1870-1918-de-la-iiie-republique-jusqu-a-la-grande-guerre/les-faits','Assemblée nationale française','Proclamation4 septembre1870.','turn249search2')
add('09-05','JPN',1905,'Le traité de Portsmouth','Le Japon et la Russie signent un traité de paix à Portsmouth, aux États-Unis. Il met fin à la guerre russo-japonaise. La date retenue ici suit le calendrier grégorien, utilisé dans le calendrier de l’application.','https://history.state.gov/historicaldocuments/frus1905/d915','Office of the Historian — texte du traité','5 septembre1905 grégorien,23 août calendrier russe.','turn249search4')
add('09-06','BGR',1885,'L’unification de la Bulgarie','L’union de la Roumélie orientale et de la principauté de Bulgarie est proclamée. Cette étape transforme la carte politique des Balkans ; elle est distincte de la déclaration d’indépendance bulgare de1908.','https://www.gov.bg/en/About-Bulgaria/HISTORY/tabsss1','Conseil des ministres bulgare','Unification6 septembre1885.','turn253search0')
add('09-07','BRA',1822,'La proclamation de l’indépendance du Brésil','Près de São Paulo, le prince Pedro proclame la rupture avec le Portugal. Le7 septembre devient le grand repère commémoratif de l’indépendance brésilienne, un processus politique et militaire qui dépasse cette seule journée.','https://mapa.an.gov.br/index.php/mapa/centrais-de-conteudo/producao/cronologias/85-periodo-joanino/1400-1822','Archives nationales brésiliennes','Chronologie7 septembre1822.','turn253search3')
add('09-08','MKD',1991,'Le référendum d’indépendance macédonien','Les électeurs se prononcent pour un État souverain lors d’un référendum. Cette étape accompagne la sortie de la Yougoslavie du pays aujourd’hui nommé Macédoine du Nord. L’adoption de la Constitution intervient ensuite en novembre.','https://arhiv.gov.mk/македонија-низ-вековите/','Archives d’État de Macédoine du Nord','Référendum8 septembre1991.','turn253search4')
add('09-09','TJK',1991,'L’indépendance du Tadjikistan','Le Conseil suprême proclame l’indépendance de la République du Tadjikistan. La résolution fixe également cette journée comme fête nationale, dans le contexte de la fin de l’Union soviétique.','https://mfa.tj/uploads/main/2013/03/tajikistan_diplomacy_the_past_and_the_present_ru2.pdf','Ministère tadjik des Affaires étrangères — documents diplomatiques','Résolution9 septembre1991.','turn253search6')
add('09-10','CHE',2002,'La Suisse rejoint les Nations unies','L’Assemblée générale admet la Confédération suisse comme membre des Nations unies. La Suisse accueillait déjà de nombreuses institutions internationales, notamment à Genève, avant de devenir elle-même membre à part entière de l’Organisation.','https://documents.un.org/api/symbol/access?l=en&s=A%2FRES%2F57%2F1&t=pdf','Nations unies — résolution57/1','Admission à la séance du10 septembre2002.','turn256search9')
add('09-11','CHL',1973,'Le coup d’État au Chili','Les forces armées et les carabiniers renversent le gouvernement de Salvador Allende. Le coup d’État ouvre une dictature et une période de répression. Cette date permet d’aborder l’histoire chilienne et la mémoire de ses victimes.','https://www.memoriachilena.gob.cl/602/w3-article-92649.html','Bibliothèque nationale du Chili — Memoria Chilena','Coup d’État11 septembre1973.','turn256search1')
add('09-12','FRA',1940,'La découverte de Lascaux','Quatre jeunes découvrent les peintures de la grotte de Lascaux, en Dordogne. Cette journée fait entrer dans l’histoire contemporaine un site majeur de l’art paléolithique, dont la conservation impose ensuite de limiter les visites de l’original.','https://archeologie.culture.gouv.fr/lascaux/fr/les-quatre-inventeurs','Ministère français de la Culture','Découverte12 septembre1940.','turn259search1')
add('09-13','ISR',1993,'La déclaration de principes d’Oslo','Israël et l’Organisation de libération de la Palestine signent à Washington une déclaration de principes. Le texte prévoit une autonomie palestinienne intérimaire et des négociations ; il ne constitue pas un accord final réglant l’ensemble du conflit.','https://www.un.org/unispal/document/auto-insert-180015/','Nations unies — texte de l’accord','Signé13 septembre1993.','turn256search3')
add('09-14','IND',1949,'Le hindi adopté comme langue officielle de l’Union','L’Assemblée constituante adopte le hindi comme langue officielle de l’Union indienne. Cela ne signifie pas que l’Inde possède une seule langue, ni que le hindi est la langue maternelle de tous ses habitants.','https://rajbhasha.gov.in/sites/default/files/niyampustak_eng_dec2021.pdf','Département indien de la langue officielle','Décision14 septembre1949.','turn259search12')
add('09-15','GTM',1821,'L’émancipation de l’Amérique centrale','Les provinces de l’ancien royaume de Guatemala se déclarent libérées de la domination espagnole. Cette étape est suivie d’une union au Mexique puis d’une fédération centraméricaine : les États actuels ne se constituent pas tous immédiatement.','https://www.banguat.gob.gt/page/epoca-independiente-y-federacion-centroamericana','Banque du Guatemala','Émancipation15 septembre1821 ; étapes ultérieures détaillées.','turn259search5')
add('09-16','MEX',1810,'Le cri de Dolores','À Dolores, Miguel Hidalgo lance l’appel qui marque le début du mouvement d’indépendance mexicain. La fête nationale rappelle ce commencement de la lutte, et non l’achèvement de l’indépendance, qui intervient en1821.','https://www.gob.mx/defensa/documentos/15-de-septiembre-de-1810-grito-de-independencia/','Ministère mexicain de la Défense','Texte confirme aube16 septembre1810 malgré URL différente.','turn259search7')
add('09-17','USA',1787,'La Constitution américaine est signée','Les délégués de la Convention constitutionnelle signent le texte à Philadelphie. La signature est une étape fondatrice, suivie par les ratifications des États et la mise en place du nouveau gouvernement fédéral.','https://www.archives.gov/milestone-documents/constitution','Archives nationales américaines — original','Signature17 septembre1787.','turn262search0')
add('09-18','CHL',1810,'La première junte de gouvernement au Chili','Une assemblée réunie à Santiago désigne une junte pour gouverner en l’absence du monarque espagnol. Cette date inaugure un processus politique qui conduit à l’indépendance ; elle ne correspond pas encore à sa proclamation définitive.','https://www.memoriachilena.gob.cl/602/w3-article-91935.html','Bibliothèque nationale du Chili','Junte nommée18 septembre1810.','turn262search2')
add('09-19','NZL',1893,'Les femmes obtiennent le droit de vote','Une nouvelle loi électorale accorde aux femmes de Nouvelle-Zélande le droit de voter aux élections parlementaires. Ce progrès résulte notamment de campagnes et pétitions ; le droit de se présenter au Parlement vient plus tard.','https://nzhistory.govt.nz/womens-suffrage-day','Ministère néo-zélandais de la Culture — NZ History','Loi signée19 septembre1893 ; éligibilité1919.','turn262search3')
add('09-20','ITA',1870,'L’entrée des troupes italiennes dans Rome','Les troupes du royaume d’Italie franchissent une brèche ouverte près de Porta Pia. La prise de Rome met fin au pouvoir territorial pontifical sur la ville et précède le plébiscite puis l’annexion au royaume.','https://www.senato.it/relazioni-con-i-cittadini/biblioteca/pubblicazioni-testi/minervaweb/allindomani-della-breccia-di','Sénat italien — bibliothèque','Entrée20 septembre1870 ; annexion ensuite.','turn262search4')
add('09-21','ARM',1991,'Le référendum d’indépendance arménien','Les citoyens votent pour une Arménie indépendante en dehors de l’Union soviétique. Ce référendum confirme la trajectoire engagée par la déclaration de souveraineté de1990 ; il constitue le repère de la fête d’indépendance actuelle.','https://www.president.am/en/general-information/','Présidence de la République d’Arménie','Référendum21 septembre1991.','turn265search0')
add('09-22','MLI',1960,'La République du Mali est proclamée','Après l’éclatement de la Fédération du Mali, la République soudanaise proclame son indépendance sous le nom de République du Mali. Cette étape est distincte de l’indépendance fédérale de juin et du retrait sénégalais d’août.','https://mjp.univ-perp.fr/constit/ml1960ind.htm','Université de Perpignan — textes des journaux officiels','Proclamation22 septembre1960 ; loi60-35.','turn265search2')
add('09-23','SAU',1932,'Le royaume prend le nom d’Arabie saoudite','Le royaume unifié sous Abdelaziz prend le nom de Royaume d’Arabie saoudite. La fête nationale commémore cette proclamation. Elle est distincte de la journée consacrée à la fondation du premier État saoudien.','https://www.mofa.gov.sa/en/ksa/Pages/default.aspx','Ministère saoudien des Affaires étrangères','Proclamation23 septembre1932.','turn265search3')
add('09-24','GNB',1973,'La Guinée-Bissau proclame son indépendance','Réunie dans la région de Boé, l’Assemblée nationale populaire proclame l’État de Guinée-Bissau. Cette déclaration intervient pendant la lutte contre le pouvoir colonial portugais ; la reconnaissance par le Portugal suit l’année suivante.','https://digitallibrary.un.org/record/859212/files/1121920-EN.pdf','Nations unies — Annuaire1973','Proclamation24 septembre1973.','turn265search7')
add('09-25','DZA',1962,'La République algérienne est proclamée','L’Assemblée nationale constituante proclame la République algérienne démocratique et populaire. Cette étape institutionnelle intervient après le référendum et l’indépendance de juillet ; elle n’est pas une seconde date d’indépendance.','https://www.joradp.dz/FTP/Jo-Francais/1962/F1962901.pdf','Journal officiel algérien — proclamation originale','Proclamation25 septembre1962.','turn267search6')
add('09-26','NZL',1907,'La Nouvelle-Zélande devient un dominion','La Nouvelle-Zélande adopte officiellement le titre de dominion dans l’Empire britannique. Ce changement est surtout symbolique : il ne lui accorde pas, ce jour-là, une indépendance juridique entièrement nouvelle.','https://nzhistory.govt.nz/page/dominion-status','Ministère néo-zélandais de la Culture — NZ History','Proclamation26 septembre1907 ; absence de changement pratique précisée.','turn267search2')
add('09-27','MEX',1821,'L’armée des Trois Garanties entre à Mexico','L’armée des Trois Garanties entre dans Mexico, événement qui marque l’aboutissement de la lutte d’indépendance. L’acte d’indépendance est signé le lendemain. Cette date complète le commencement du mouvement commémoré le16 septembre.','https://www.gob.mx/defensa/documentos/27-de-septiembre-de-1821-consumacion-de-la-independencia','Ministère mexicain de la Défense','Entrée27 septembre1821, acte le lendemain.','turn267search4')
add('09-28','PSE',1995,'L’accord intérimaire dit Oslo II','L’Organisation de libération de la Palestine et Israël signent un accord intérimaire sur la Cisjordanie et la bande de Gaza. Le texte organise notamment des transferts de responsabilités ; il ne règle pas définitivement les questions du conflit.','https://www.un.org/unispal/document/auto-insert-185434/','Nations unies — texte de l’accord','Signature28 septembre1995.','turn267search5')
add('09-29','GBR',1829,'Les premières patrouilles de la Metropolitan Police','La nouvelle police métropolitaine commence à patrouiller dans Londres. Cette création associée à Robert Peel constitue une étape de l’histoire de la police britannique, distincte des forces et dispositifs qui existaient auparavant.','https://cdn.nationalarchives.gov.uk/documents/the-metropolitan-police.pdf','Archives nationales britanniques','Premier jour de la nouvelle force29 septembre1829.','turn270search3')
add('09-30','BWA',1966,'Le Bechuanaland devient le Botswana','L’ancien protectorat britannique du Bechuanaland devient un État indépendant sous le nom de République du Botswana. Seretse Khama, jusqu’alors Premier ministre, devient son premier président.','https://www.parliament.gov.bw/index.php?id=6&option=com_content&view=article','Parlement du Botswana','Indépendance et nouveau nom30 septembre1966.','turn269search3')
